import { createClient } from '@supabase/supabase-js';
import './style.css';
const url=import.meta.env.VITE_SUPABASE_URL,key=import.meta.env.VITE_SUPABASE_ANON_KEY;
const db=url&&key?createClient(url,key):null;
const app=document.querySelector('#app');
const state={session:null,profile:null,projects:[],project:null,observations:[],lang:localStorage.getItem('ge_lang')||'en',page:'home',detail:null,history:[]};
const tr=(en,es)=>state.lang==='es'?es:en;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v?new Intl.DateTimeFormat(state.lang==='es'?'es-US':'en-US',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'';
const localDateKey=(v=new Date())=>{const d=new Date(v),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};
const deviceZone=()=>Intl.DateTimeFormat().resolvedOptions().timeZone||'Local';
const error=e=>{document.querySelector('#message').textContent=e?.message||String(e)};
let restoringHistory=false;


const DRAFT_FORMS={
 'observation':'observation',
 'correction':'correction',
 'walk-form':'daily_safety_walk',
 'incident-form':'incident',
 'equipment-form':'equipment_inspection',
 'discipline-form':'disciplinary_action'
};
const draftTimers=new Map();
const draftFileState=new Map();
const draftContextKey=(type,key='default')=>`${state.profile?.id||'guest'}:${state.project||'none'}:${type}:${key}`;
const draftLocalKey=(type,key='default')=>`ge_draft_v1:${state.profile?.id||'guest'}:${state.project||'none'}:${type}:${key}`;
function serializeDraftForm(form,type=null,key='default'){
 const data={};
 for(const el of form.elements){
  if(!el.name||el.disabled||el.type==='file'||['submit','button','password'].includes(el.type))continue;
  if(el.type==='radio'){if(el.checked)data[el.name]=el.value;continue}
  if(el.type==='checkbox'){data[el.name]=!!el.checked;continue}
  if(el.tagName==='SELECT'&&el.multiple){data[el.name]=[...el.selectedOptions].map(o=>o.value);continue}
  data[el.name]=el.value;
 }
 if(type){const files=draftFileState.get(draftContextKey(type,key));if(files&&Object.keys(files).length)data.__files=files}
 return data;
}
function applyDraftForm(form,data={}){
 for(const el of form.elements){
  if(!el.name||!(el.name in data)||el.type==='file'||el.type==='password')continue;
  const v=data[el.name];
  if(el.type==='radio')el.checked=el.value===v;
  else if(el.type==='checkbox')el.checked=!!v;
  else if(el.tagName==='SELECT'&&el.multiple){for(const o of el.options)o.selected=Array.isArray(v)&&v.includes(o.value)}
  else el.value=v??'';
  el.dispatchEvent(new Event('change',{bubbles:true}));
 }
}
function setDraftStatus(form,text,kind='saved'){
 let node=form.querySelector('.draft-save-status');
 if(!node){node=document.createElement('div');node.className='draft-save-status';form.prepend(node)}
 node.dataset.kind=kind;node.textContent=text;
}
async function persistDraft(form,type,key='default'){
 if(!state.profile?.id||!state.project)return;
 const payload=serializeDraftForm(form,type,key),localKey=draftLocalKey(type,key),record={payload,updated_at:new Date().toISOString()};
 try{localStorage.setItem(localKey,JSON.stringify(record))}catch{}
 setDraftStatus(form,tr('Saving draft…','Guardando borrador…'),'saving');
 const result=await db.from('form_drafts').upsert({user_id:state.profile.id,project_id:state.project,form_type:type,draft_key:key,payload,current_field:document.activeElement?.name||null,status:'active',updated_at:record.updated_at},{onConflict:'user_id,project_id,form_type,draft_key'});
 if(result.error){setDraftStatus(form,tr('Saved on this device · Cloud sync pending','Guardado en este dispositivo · Sincronización pendiente'),'local');return}
 setDraftStatus(form,tr('Draft saved ✓','Borrador guardado ✓'),'saved');
}
async function uploadDraftFiles(form,type,key,input){
 if(!input?.name||!input.files?.length)return;
 const ctx=draftContextKey(type,key),all={...(draftFileState.get(ctx)||{})},old=all[input.name]||[];
 if(old.length)await db.storage.from('draft-evidence').remove(old.map(x=>x.path));
 const saved=[];
 for(const original of [...input.files]){
  if(original.size>10*1024*1024)throw Error(tr('Each draft photo must be 10 MB or less.','Cada foto del borrador debe ser de 10 MB o menos.'));
  let file=await normalizeReportImage(original);
  if(!file.type.startsWith('image/'))throw Error(tr('Only supported images can be saved as draft evidence.','Solo imágenes compatibles pueden guardarse como evidencia temporal.'));
  const ext=file.type.split('/')[1]?.replace(/[^a-z0-9]/gi,'')||'jpg';
  const safeName=input.name.replace(/[^a-z0-9_-]/gi,'_');
  const path=`${state.profile.id}/${state.project}/${type}/${encodeURIComponent(key)}/${safeName}/${crypto.randomUUID()}.${ext}`;
  const up=await db.storage.from('draft-evidence').upload(path,file,{contentType:file.type});
  if(up.error)throw up.error;
  saved.push({path,name:file.name,type:file.type,size:file.size});
 }
 all[input.name]=saved;draftFileState.set(ctx,all);renderDraftFileBadges(form,all);await persistDraft(form,type,key);
}
function renderDraftFileBadges(form,files={}){
 form.querySelectorAll('.draft-file-restored').forEach(x=>x.remove());
 for(const [name,items] of Object.entries(files)){
  if(!items?.length)continue;const input=[...form.querySelectorAll('input[type=file]')].find(x=>x.name===name);if(!input)continue;
  const note=document.createElement('div');note.className='draft-file-restored';note.textContent=tr(`${items.length} saved draft photo(s) protected in cloud ✓`,`${items.length} foto(s) del borrador protegida(s) en la nube ✓`);input.insertAdjacentElement('afterend',note);
 }
}
async function draftFilesFor(form,type,key='default',name){
 const input=[...form.querySelectorAll('input[type=file]')].find(x=>x.name===name);
 if(input?.files?.length)return [...input.files];
 const items=(draftFileState.get(draftContextKey(type,key))||{})[name]||[],files=[];
 for(const item of items){const d=await db.storage.from('draft-evidence').download(item.path);if(d.error)throw d.error;files.push(new File([d.data],item.name||'draft-photo.jpg',{type:item.type||d.data.type||'image/jpeg'}))}
 return files;
}

async function clearDraft(type,key='default'){
 try{localStorage.removeItem(draftLocalKey(type,key))}catch{}
 const ctx=draftContextKey(type,key),files=draftFileState.get(ctx)||{};
 if(state.profile?.id&&state.project){
  if(!Object.keys(files).length){const q=await db.from('form_drafts').select('payload').eq('user_id',state.profile.id).eq('project_id',state.project).eq('form_type',type).eq('draft_key',key).maybeSingle();Object.assign(files,q.data?.payload?.__files||{})}
  const paths=Object.values(files).flat().map(x=>x.path).filter(Boolean);if(paths.length)await db.storage.from('draft-evidence').remove(paths);
  await db.from('form_drafts').delete().eq('user_id',state.profile.id).eq('project_id',state.project).eq('form_type',type).eq('draft_key',key);
 }
 draftFileState.delete(ctx);
}
async function restoreDraft(form,type,key='default'){
 let local=null,cloud=null;
 try{local=JSON.parse(localStorage.getItem(draftLocalKey(type,key))||'null')}catch{}
 if(state.profile?.id&&state.project){
  const q=await db.from('form_drafts').select('payload,updated_at,current_field').eq('user_id',state.profile.id).eq('project_id',state.project).eq('form_type',type).eq('draft_key',key).eq('status','active').maybeSingle();
  if(!q.error)cloud=q.data;
 }
 const source=!cloud?local:!local?cloud:(new Date(cloud.updated_at)>=new Date(local.updated_at)?cloud:local);
 if(!source?.payload)return false;
 applyDraftForm(form,source.payload);
 if(source.payload.__files){draftFileState.set(draftContextKey(type,key),source.payload.__files);renderDraftFileBadges(form,source.payload.__files)}
 setDraftStatus(form,tr('Unfinished draft restored · '+fmt(source.updated_at),'Borrador sin terminar restaurado · '+fmt(source.updated_at)),'restored');
 if(source.current_field){const el=form.elements[source.current_field];if(el)el.scrollIntoView({block:'center'})}
 return true;
}
async function enableAutoDraft(form,type,key='default'){
 if(!form||!type)return;
 await restoreDraft(form,type,key);
 const schedule=()=>{
  const timerKey=type+':'+key;clearTimeout(draftTimers.get(timerKey));
  setDraftStatus(form,tr('Saving draft…','Guardando borrador…'),'saving');
  draftTimers.set(timerKey,setTimeout(()=>persistDraft(form,type,key),650));
 };
 form.addEventListener('input',schedule);
 form.addEventListener('change',schedule);
 form.addEventListener('focusin',schedule);
 form.addEventListener('change',e=>{if(e.target?.type==='file'&&e.target.files?.length)uploadDraftFiles(form,type,key,e.target).catch(error)});
 const flush=()=>{if(document.visibilityState==='hidden')persistDraft(form,type,key)};
 document.addEventListener('visibilitychange',flush);
 form.dataset.autoDraft='true';
}
function activateOperationalDrafts(){
 for(const [id,type] of Object.entries(DRAFT_FORMS)){
  const form=document.getElementById(id);if(!form||form.dataset.autoDraft)return;
  const key=id==='correction'?(state.detail||'default'):'default';
  enableAutoDraft(form,type,key);
 }
}

async function normalizeReportImage(file){
  if(!(file instanceof File)||!file.size)return file;
  const heic=/image\/hei[cf]/i.test(file.type)||/\.hei[cf]$/i.test(file.name);
  if(!heic)return file;
  if(typeof window.heic2any!=='function')throw new Error(tr('This iPhone HEIC photo could not be converted. Please try again after refreshing the app.','Esta foto HEIC de iPhone no pudo convertirse. Actualiza la app e intenta nuevamente.'));
  const converted=await window.heic2any({blob:file,toType:'image/jpeg',quality:.9});
  const blob=Array.isArray(converted)?converted[0]:converted;
  return new File([blob],(file.name||'photo').replace(/\.hei[cf]$/i,'')+'.jpg',{type:'image/jpeg',lastModified:Date.now()});
}
async function waitForReportImages(report){
  const imgs=[...report.querySelectorAll('img')];
  await Promise.all(imgs.map(img=>new Promise(resolve=>{
    if(img.complete&&img.naturalWidth>0)return resolve();
    let done=false;const finish=()=>{if(done)return;done=true;clearTimeout(timer);resolve()};
    const timer=setTimeout(finish,12000);img.addEventListener('load',finish,{once:true});img.addEventListener('error',finish,{once:true});
  })));
  await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
}
function reportPdfFilename(report){
  const title=(report.querySelector('h1')?.textContent||'G&E Safety Report').trim().replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'');
  return `${title||'GE-Safety-Report'}-${localDateKey()}.pdf`;
}
function currentReportIdentity(report){
 const map={report:'daily_report',observationReport:'observation',safetyWalkReport:'daily_safety_walk',disciplineReport:'disciplinary_action',incidentReport:'incident',equipmentInspectionReport:'equipment_inspection'};
 const reportType=map[state.page];if(!reportType||!state.project||!state.profile)return null;
 let reportNumber=(report.querySelector('.ewr-id strong')?.textContent||report.querySelector('.print-report-number b')?.textContent||report.querySelector('.eq-doc b')?.textContent||report.querySelector('.ir-title b')?.textContent||report.querySelector('.dr-doc p')?.textContent?.split('·')[0]||'').trim();
 if(!reportNumber)reportNumber='DSR-'+localDateKey().replaceAll('-','')+'-'+String(state.project).slice(0,6).toUpperCase();
 return {reportType,reportNumber,sourceId:state.page==='report'?null:state.detail||null,title:(report.querySelector('h1')?.textContent||'G&E Safety Report').trim()};
}
async function registerFinalReport(blob,report){
 const meta=currentReportIdentity(report);if(!meta)return null;
 const existing=await db.from('report_documents').select('id,pdf_path,report_number').eq('project_id',state.project).eq('report_number',meta.reportNumber).maybeSingle();
 if(existing.error)throw existing.error;if(existing.data)return existing.data;
 const safe=meta.reportNumber.replace(/[^a-z0-9_-]+/gi,'-'),path=`${state.project}/${meta.reportType}/${safe}-${Date.now()}.pdf`;
 const stored=await db.storage.from('final-reports').upload(path,blob,{contentType:'application/pdf',cacheControl:'3600',upsert:false});if(stored.error)throw stored.error;
 const doc=await db.from('report_documents').insert({project_id:state.project,report_type:meta.reportType,source_id:meta.sourceId,report_number:meta.reportNumber,title:meta.title,document_status:'final',version:1,snapshot:{generated_at:new Date().toISOString(),language:state.lang,source_page:state.page},pdf_path:path,created_by:state.profile.id,finalized_by:state.profile.id,finalized_at:new Date().toISOString()}).select('id,pdf_path,report_number').single();
 if(doc.error){await db.storage.from('final-reports').remove([path]);throw doc.error}
 await db.from('report_document_events').insert({report_document_id:doc.data.id,actor_id:state.profile.id,event_type:'finalized',detail:{source_page:state.page}});
 return doc.data;
}
async function buildReportPdf(){
  const report=document.querySelector('article.report');
  if(!report)throw new Error(tr('Report document not found.','No se encontró el documento del reporte.'));
  if(typeof window.html2pdf!=='function')throw new Error(tr('PDF service is still loading. Please try again.','El servicio PDF aún está cargando. Intente nuevamente.'));
  await waitForReportImages(report);
  const options={
    margin:[0.25,0.25,0.3,0.25],
    filename:reportPdfFilename(report),
    image:{type:'jpeg',quality:0.98},
    html2canvas:{scale:2,useCORS:true,allowTaint:false,backgroundColor:'#ffffff',logging:false},
    jsPDF:{unit:'in',format:'letter',orientation:'portrait'},
    pagebreak:{mode:['css','legacy'],avoid:['.report-photo','figure','.ewr-hazard','.report-section']}
  };
  const worker=window.html2pdf().set(options).from(report);
  const blob=await worker.outputPdf('blob');
  await registerFinalReport(blob,report);
  return {blob,filename:options.filename,report};
}
async function runPdfAction(action,button){
  const original=button?.innerHTML;
  try{
    if(button){button.disabled=true;button.textContent=tr('Preparing PDF…','Preparando PDF…')}
    const {blob,filename,report}=await buildReportPdf();
    if(action==='view'){
      const u=URL.createObjectURL(blob);window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),120000);return;
    }
    if(action==='download'){
      const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);return;
    }
    const file=new File([blob],filename,{type:'application/pdf'});
    const title=(report.querySelector('h1')?.textContent||'G&E Safety Report').trim();
    if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){
      await navigator.share({title,text:tr('G&E Safety Department report','Reporte de G&E Safety Department'),files:[file]});return;
    }
    const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);
    location.href='mailto:?subject='+encodeURIComponent(title)+'&body='+encodeURIComponent(tr('The PDF report has been downloaded. Please attach it to this email.','El reporte PDF fue descargado. Por favor adjúntelo a este correo.'));
  }catch(e){if(e?.name!=='AbortError')error(e)}
  finally{if(button){button.disabled=false;button.innerHTML=original}}
}
function installReportDocumentActions(){
  const report=document.querySelector('article.report');if(!report)return;
  let bar=document.querySelector('.report-actions');
  if(!bar){bar=document.createElement('div');bar.className='report-actions';report.before(bar)}
  if(bar.dataset.pdfActions==='1')return;
  bar.dataset.pdfActions='1';
  const actions=document.createElement('div');actions.className='pdf-document-actions';
  actions.innerHTML='<button type="button" class="secondary pdf-view">◉ '+tr('View PDF','Ver PDF')+'</button><button type="button" class="pdf-download">⇩ '+tr('Download PDF','Descargar PDF')+'</button><button type="button" class="secondary pdf-share">↗ '+tr('Share / Email','Compartir / Correo')+'</button>';
  bar.appendChild(actions);
  actions.querySelector('.pdf-view').onclick=e=>runPdfAction('view',e.currentTarget);
  actions.querySelector('.pdf-download').onclick=e=>runPdfAction('download',e.currentTarget);
  actions.querySelector('.pdf-share').onclick=e=>runPdfAction('share',e.currentTarget);
}
const reportActionObserver=new MutationObserver(()=>{if(document.querySelector('article.report'))installReportDocumentActions()});
reportActionObserver.observe(app,{childList:true,subtree:true});
function navigate(page,detail=null,{replace=false}={}){state.page=page;state.detail=detail;const entry={geSafety:true,page,detail};if(!restoringHistory){if(replace)history.replaceState(entry,'',location.href);else history.pushState(entry,'',location.href)}render()}
function back(){if(history.state?.geSafety&&state.page!=='home')history.back();else navigate('home',null,{replace:true})}
function frame(body){app.innerHTML=`<header><div class="brand"><img src="/ge-logo.png" alt="G&E Florida Contractors"><span>G&E <small>SAFETY DEPARTMENT</small></span></div><nav>${state.session&&state.page!=='home'?'<button id="global-back" class="home-nav" aria-label="'+tr('Back','Atrás')+'">← <span>'+tr('Back','Atrás')+'</span></button><button id="global-home" class="home-nav" aria-label="'+tr('Home','Inicio')+'">⌂ <span>'+tr('Home','Inicio')+'</span></button>':''}${state.session?'<button id="notification-menu" class="notification-menu" aria-label="'+tr('Notifications','Notificaciones')+'">🔔<span id="notification-count"></span></button>':''}<button id="language">${state.lang==='es'?'EN':'ES'}</button>${state.session?'<button id="password-menu">'+tr('Settings','Configuración')+'</button><button id="logout">'+tr('Sign out','Salir')+'</button>':''}</nav></header><div id="message" role="alert"></div><main>${body}</main>${state.session&&state.page!=='home'?'<div class="device-back-bar"><button id="mobile-global-back" class="mobile-nav-button mobile-back-button" aria-label="'+tr('Back','Atrás')+'"><span>←</span><small>'+tr('Back','Atrás')+'</small></button><button id="mobile-global-home" class="mobile-nav-button mobile-home-button" aria-label="'+tr('Home','Inicio')+'"><span>⌂</span><small>'+tr('Home','Inicio')+'</small></button></div>':''}`;const mb=document.querySelector('#mobile-global-back'),mh=document.querySelector('#mobile-global-home');if(mb)mb.onclick=back;if(mh)mh.onclick=()=>navigate('home');document.querySelector('#language').onclick=()=>{state.lang=state.lang==='es'?'en':'es';localStorage.setItem('ge_lang',state.lang);render()};if(state.session){const nm=document.querySelector('#notification-menu');if(nm){nm.onclick=()=>navigate('notifications');db.from('notifications').select('id',{count:'exact',head:true}).is('read_at',null).then(({count})=>{const el=document.querySelector('#notification-count');if(el&&count){el.textContent=count>99?'99+':String(count);el.classList.add('show')}})}const b=document.querySelector('#global-back');if(b)b.onclick=back;const h=document.querySelector('#global-home');if(h)h.onclick=()=>navigate('home');document.querySelector('#logout').onclick=()=>db.auth.signOut();document.querySelector('#password-menu').onclick=()=>navigate('setPassword')}queueMicrotask(activateOperationalDrafts)}
function splash(){sessionStorage.setItem('ge_splash_seen','1');app.innerHTML=`<section class="ge-splash"><div class="splash-overlay"></div><div class="splash-brand"><img src="/ge-logo.png" alt="G&E Florida Contractors"><h1>SAFETY DEPARTMENT</h1><p>PEOPLE &nbsp; | &nbsp; SAFETY &nbsp; | &nbsp; RESULTS</p></div><div class="splash-bottom"><strong>${tr('BUILDING A SAFER TOMORROW','CONSTRUYENDO UN MAÑANA MÁS SEGURO')}</strong><span>G&E SAFETY • v1.0</span></div></section>`;setTimeout(()=>{if(!state.session)login()},1350)}
function render(){if(!db)return frame(`<section class="card"><h1>${tr('Setup required','Configuración necesaria')}</h1><p>${tr('Create a Supabase project and copy .env.example to .env with its URL and publishable key.','Cree un proyecto de Supabase y copie .env.example a .env con la URL y clave pública.')}</p></section>`);if(!state.session){if(!sessionStorage.getItem('ge_splash_seen'))return splash();return login();}if(state.page==='setPassword')return setPassword();if(state.page==='profile')return profilePage();if(!state.profile)return frame(`<section class="card"><h1>${tr('Access pending','Acceso pendiente')}</h1><p>${tr('An administrator must add your company email as a team member.','Un administrador debe agregar su correo de la compañía al equipo.')}</p></section>`);startAppPresence();if(!state.projects.length&&state.profile.role!=='admin')return frame(`<section class="card"><h1>${tr('Waiting for project access','Esperando acceso al proyecto')}</h1><p>${tr('An administrator must assign you to a project.','Un administrador debe asignarte a un proyecto.')}</p></section>`);if(state.page==='notifications')return notificationsPage();if(state.page==='admin')return admin();if(state.page==='observations')return observationsList();if(state.page==='corrections')return correctionsList();if(state.page==='cloudBackup')return cloudBackup();if(state.page==='equipmentInspection')return equipmentInspection();if(state.page==='equipmentInspectionReport')return equipmentInspectionReport();if(state.page==='incident')return incidentReportForm();if(state.page==='incidentReport')return incidentReportView();if(state.page==='discipline')return discipline();if(state.page==='disciplineReport')return disciplineReport();if(state.page==='safetyWalk')return safetyWalk();if(state.page==='safetyWalkReport')return safetyWalkReport();if(state.page==='observationReport')return observationReport();if(state.page==='detail')return detail();if(state.page==='new')return newObservation();if(state.page==='reportCenter')return reportCenter();if(state.page==='report')return report();home()}
async function notificationsPage(){const q=await db.from('notifications').select('id,project_id,observation_id,type,title,message,priority,read_at,created_at').order('created_at',{ascending:false}).limit(100);if(q.error)return error(q.error);const rows=q.data||[],unread=rows.filter(x=>!x.read_at).length;frame(`<section class="notifications-shell"><div class="section-heading"><div><h1>🔔 ${tr('Notifications','Notificaciones')}</h1><p>${tr('Safety actions requiring your attention and follow-up.','Acciones de Safety que requieren su atención y seguimiento.')}</p></div>${unread?`<button class="secondary" id="mark-all">${tr('Mark all read','Marcar todas leídas')}</button>`:''}</div><div class="notification-summary"><strong>${unread}</strong><span>${tr('Unread','Sin leer')}</span></div><div class="notification-list">${rows.length?rows.map(n=>`<button class="notification-card ${n.read_at?'read':'unread'} ${esc(n.priority)}" data-id="${n.id}" data-observation="${n.observation_id||''}"><div class="notification-icon">${n.type==='observation_reminder'?'⏱':'⚠'}</div><div><div class="notification-card-head"><strong>${esc(n.title)}</strong><time>${esc(fmt(n.created_at))}</time></div><p>${esc(n.message)}</p><small>${n.type==='observation_reminder'?tr('30-minute follow-up reminder','Recordatorio de seguimiento de 30 minutos'):tr('New assigned activity','Nueva actividad asignada')}</small></div></button>`).join(''):`<div class="empty-state"><strong>${tr('No notifications','No hay notificaciones')}</strong><p>${tr('You are up to date.','Está al día.')}</p></div>`}</div></section>`);document.querySelectorAll('.notification-card').forEach(el=>el.onclick=async()=>{await db.from('notifications').update({read_at:new Date().toISOString()}).eq('id',el.dataset.id);if(el.dataset.observation)navigate('detail',el.dataset.observation);else render()});const all=document.querySelector('#mark-all');if(all)all.onclick=async()=>{const r=await db.from('notifications').update({read_at:new Date().toISOString()}).is('read_at',null);if(r.error)return error(r.error);render()}}

function login(mode='signIn'){const signup=mode==='signUp';app.innerHTML=`<div class="auth-experience"><section class="auth-panel"><div class="auth-language"><button id="language">${state.lang==='es'?'🇺🇸 English':'🇪🇸 Español'}</button></div><div class="auth-brand"><img src="/ge-logo.png" alt="G&E Florida Contractors"><strong>G&E SAFETY DEPARTMENT</strong><span>PEOPLE &nbsp; | &nbsp; SAFETY &nbsp; | &nbsp; RESULTS</span></div><div class="auth-copy"><h1>${signup?tr('Create Account','Crear Cuenta'):tr('Sign In','Iniciar Sesión')}</h1><p>${tr('Access your G&E Safety account','Accede a tu cuenta de G&E Safety')}</p></div><div id="message" role="alert"></div><form id="login" class="auth-form">${signup?`<label>${tr('Full name','Nombre completo')}<input name="name" required autocomplete="name" placeholder="${tr('Full name','Nombre completo')}"></label>`:''}<label>${tr('Company Email','Correo de la Compañía')}<input type="email" name="email" required autocomplete="email" placeholder="name@geflcontractors.com"></label><label>${tr('Password','Contraseña')}<div class="password-field"><input id="auth-password" type="password" name="password" required minlength="8" autocomplete="${signup?'new-password':'current-password'}" placeholder="••••••••"><button type="button" id="toggle-password" aria-label="${tr('Show password','Mostrar contraseña')}">◉</button></div></label>${!signup?`<button type="button" class="auth-forgot" id="forgot">${tr('Forgot Password?','¿Olvidaste tu contraseña?')}</button>`:''}<button class="auth-submit">${signup?tr('Create Account','Crear Cuenta'):tr('Sign In','Entrar')}</button></form><div class="auth-switch"><span>${signup?tr('Already have an account?','¿Ya tienes una cuenta?'):tr('Company access only','Acceso exclusivo de la compañía')}</span><button id="mode">${signup?tr('Sign In','Entrar'):tr('Create Account','Crear Cuenta')}</button></div><div class="auth-footer">SAFE PEOPLE &nbsp; • &nbsp; STRONG PROJECTS &nbsp; • &nbsp; BRIGHTER TOMORROW</div></section><aside class="auth-visual"><div class="auth-visual-shade"></div><img src="/ge-logo.png" alt="" aria-hidden="true"><div><small>G&E FLORIDA CONTRACTORS</small><h2>${tr('Building a Safer Tomorrow','Construyendo un Mañana Más Seguro')}</h2><p>${tr('Professional construction safety management, field reporting and accountability.','Gestión profesional de seguridad, reportes de campo y responsabilidad.')}</p></div></aside></div>`;document.querySelector('#language').onclick=()=>{state.lang=state.lang==='es'?'en':'es';localStorage.setItem('ge_lang',state.lang);login(mode)};document.querySelector('#mode').onclick=()=>login(signup?'signIn':'signUp');if(!signup)document.querySelector('#forgot').onclick=()=>forgotPassword();const tp=document.querySelector('#toggle-password');if(tp)tp.onclick=()=>{const p=document.querySelector('#auth-password');p.type=p.type==='password'?'text':'password'};document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const email=String(f.get('email')).trim();const password=String(f.get('password'));if(signup&&!email.toLowerCase().endsWith('@geflcontractors.com'))return error(tr('Use your @geflcontractors.com company email','Usa tu correo de compañía @geflcontractors.com'));const result=signup?await db.auth.signUp({email,password,options:{data:{name:String(f.get('name')).trim()}}}):await db.auth.signInWithPassword({email,password});if(result.error)return error(result.error);if(signup&&!result.data.session){frame(`<section class="card narrow"><h1>${tr('Check your email','Revisa tu correo')}</h1><p>${tr('Confirm your email, then return to sign in.','Confirma tu correo y vuelve a iniciar sesión.')}</p><button id="back-login">${tr('Sign in','Entrar')}</button></section>`);document.querySelector('#back-login').onclick=()=>login()}}}
function forgotPassword(){frame(`<section class="card narrow"><h1>${tr('Reset password','Restablecer contraseña')}</h1><form id="reset"><label>${tr('Company email','Correo de la compañía')}<input type="email" name="email" required></label><button>${tr('Send recovery link','Enviar enlace')}</button></form><p><button class="secondary" id="back-login">${tr('Back to sign in','Volver a entrar')}</button></p></section>`);document.querySelector('#back-login').onclick=()=>login();document.querySelector('#reset').onsubmit=async e=>{e.preventDefault();const email=String(new FormData(e.target).get('email')).trim();const {error:err}=await db.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin});if(err)return error(err);frame(`<section class="card narrow"><h1>${tr('Check your email','Revisa tu correo')}</h1><p>${tr('If this account exists, a recovery link was sent.','Si la cuenta existe, se envió un enlace de recuperación.')}</p></section>`)}}
async function signedDisplayImage(bucket,path,expires=3600){
 if(!path)return '';
 const signed=await db.storage.from(bucket).createSignedUrl(path,expires);
 if(signed.error||!signed.data?.signedUrl)return '';
 const raw=signed.data.signedUrl;
 if(!/\.hei[cf](?:$|\?)/i.test(path)||typeof window.heic2any!=='function')return raw;
 try{
  const response=await fetch(raw);if(!response.ok)throw new Error('image fetch failed');
  const source=await response.blob(),converted=await window.heic2any({blob:source,toType:'image/jpeg',quality:.9});
  const jpeg=Array.isArray(converted)?converted[0]:converted;
  return URL.createObjectURL(jpeg);
 }catch{return raw}
}
async function profileAvatarUrl(path){return signedDisplayImage('profile-avatars',path,3600)}
async function cropProfilePhoto(file){
 const url=URL.createObjectURL(file),img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});
 return await new Promise(resolve=>{let zoom=1,ox=0,oy=0,drag=false,sx=0,sy=0;
  const overlay=document.createElement('div');overlay.className='profile-crop-overlay';
  overlay.innerHTML=`<div class="profile-crop-card"><div class="profile-crop-head"><div><strong>${tr('Adjust profile photo','Ajustar foto de perfil')}</strong><small>${tr('Move and zoom until the photo fits the circle.','Mueve y acerca hasta que la foto encaje en el círculo.')}</small></div><button type="button" id="crop-close">×</button></div><div class="profile-crop-stage"><canvas id="profile-crop-canvas" width="640" height="640"></canvas><div class="profile-crop-ring"></div></div><label class="profile-crop-zoom">${tr('Zoom','Zoom')}<input id="profile-crop-range" type="range" min="1" max="3" step=".01" value="1"></label><div class="profile-crop-actions"><button type="button" class="secondary" id="crop-cancel">${tr('Cancel','Cancelar')}</button><button type="button" id="crop-save">${tr('Use this photo','Usar esta foto')}</button></div></div>`;
  document.body.appendChild(overlay);const canvas=overlay.querySelector('canvas'),ctx=canvas.getContext('2d'),range=overlay.querySelector('#profile-crop-range');
  const base=Math.max(canvas.width/img.width,canvas.height/img.height);
  const clamp=()=>{const w=img.width*base*zoom,h=img.height*base*zoom;ox=Math.min(Math.max(ox,(canvas.width-w)/2),(w-canvas.width)/2);oy=Math.min(Math.max(oy,(canvas.height-h)/2),(h-canvas.height)/2)};
  const draw=()=>{clamp();ctx.clearRect(0,0,640,640);const w=img.width*base*zoom,h=img.height*base*zoom;ctx.drawImage(img,(640-w)/2+ox,(640-h)/2+oy,w,h)};
  const point=e=>{const r=canvas.getBoundingClientRect(),t=e.touches?.[0]||e;return{x:(t.clientX-r.left)*640/r.width,y:(t.clientY-r.top)*640/r.height}};
  const start=e=>{drag=true;const p=point(e);sx=p.x-ox;sy=p.y-oy;e.preventDefault()},move=e=>{if(!drag)return;const p=point(e);ox=p.x-sx;oy=p.y-sy;draw();e.preventDefault()},end=()=>drag=false;
  canvas.addEventListener('pointerdown',start);window.addEventListener('pointermove',move);window.addEventListener('pointerup',end);
  range.oninput=()=>{zoom=Number(range.value);draw()};draw();
  const finish=v=>{URL.revokeObjectURL(url);overlay.remove();resolve(v)};
  overlay.querySelector('#crop-close').onclick=()=>finish(null);overlay.querySelector('#crop-cancel').onclick=()=>finish(null);
  overlay.querySelector('#crop-save').onclick=()=>canvas.toBlob(blob=>finish(blob?new File([blob],'profile-photo.jpg',{type:'image/jpeg',lastModified:Date.now()}):null),'image/jpeg',.92);
 });
}
async function profilePage(){
 const p=state.profile||{},avatar=await profileAvatarUrl(p.avatar_path);
 const first=p.first_name||String(p.name||'').trim().split(/\s+/)[0]||'',last=p.last_name||String(p.name||'').trim().split(/\s+/).slice(1).join(' ');
 const full=[first,last].filter(Boolean).join(' ')||p.name||tr('My Profile','Mi Perfil'),initials=full.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
 const jobsite=state.projects.find(x=>x.id===p.jobsite_id);
 frame(`<section class="profile-shell"><div class="profile-card profile-card-pro"><header class="profile-pro-head"><div class="profile-avatar-wrap"><div id="profile-avatar-large" class="profile-avatar-large"></div><label class="profile-photo-button">📷 <span>${tr('Change photo','Cambiar foto')}</span><input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" hidden></label></div><div class="profile-info"><small>${tr('TEAM MEMBER PROFILE','PERFIL DEL INTEGRANTE')}</small><h1>${esc(full)}</h1><p>${esc(p.email||state.session?.user?.email||'')}</p><span>${esc((p.role||'worker').replaceAll('_',' '))}</span></div></header><form id="member-profile-form" class="profile-form"><div class="profile-form-grid"><label>${tr('First name','Nombre')}<input name="first_name" maxlength="60" required value="${esc(first)}"></label><label>${tr('Last name','Apellido')}<input name="last_name" maxlength="80" required value="${esc(last)}"></label><label>${tr('Position / Job title','Cargo / Posición')}<input name="position" maxlength="100" required value="${esc(p.position||'')}" placeholder="${tr('Example: Safety Coordinator','Ejemplo: Safety Coordinator')}"></label><label>${tr('Mobile phone','Teléfono móvil')}<input name="phone" type="tel" inputmode="tel" maxlength="20" value="${esc(p.phone||'')}" placeholder="+1 305 555 0123"></label><label>${tr('Primary Jobsite','Jobsite principal')}<select name="jobsite_id" required><option value="">${tr('Select jobsite','Seleccionar jobsite')}</option>${state.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===p.jobsite_id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><label class="profile-bio-label">${tr('About me','Acerca de mí')}<textarea name="bio" maxlength="500" placeholder="${tr('Write a short professional description about yourself, your experience or safety responsibilities.','Escribe una breve descripción profesional sobre ti, tu experiencia o responsabilidades de seguridad.')}">${esc(p.bio||'')}</textarea><small>${tr('Maximum 500 characters.','Máximo 500 caracteres.')}</small></label><div class="profile-notification-settings"><div><strong>${tr('Safety Notifications','Notificaciones de Safety')}</strong><small>${tr('Receive a 24-hour summary of new observations and cases that remain open.','Reciba cada 24 horas un resumen de observaciones nuevas y casos que continúan abiertos.')}</small></div><label><input type="checkbox" name="notify_sms" ${p.notify_sms!==false?'checked':''}> ${tr('SMS to my mobile phone every 24 hours','SMS a mi teléfono móvil cada 24 horas')}</label><label><input type="checkbox" name="notify_app" ${p.notify_app!==false?'checked':''}> ${tr('Notifications inside the app','Notificaciones dentro de la app')}</label><label><input type="checkbox" name="notify_email" ${p.notify_email!==false?'checked':''}> ${tr('Email notifications','Notificaciones por correo')}</label></div><div class="profile-summary"><div><small>${tr('COMPANY EMAIL','CORREO DE COMPAÑÍA')}</small><strong>${esc(p.email||state.session?.user?.email||'—')}</strong></div><div><small>${tr('SYSTEM ROLE','ROL DEL SISTEMA')}</small><strong>${esc((p.role||'worker').replaceAll('_',' '))}</strong></div><div><small>${tr('CURRENT JOBSITE','JOBSITE ACTUAL')}</small><strong>${esc(jobsite?.name||tr('Not assigned','No asignado'))}</strong></div></div><div id="profile-message" class="profile-message" aria-live="polite"></div><div class="profile-form-actions"><button type="submit">${tr('Save profile','Guardar perfil')}</button></div></form><div class="profile-note">${tr('Your profile information is used across G&E Safety reports and team activity. Your system role and permissions can only be changed by an administrator.','La información de tu perfil se utiliza en los reportes de G&E Safety y la actividad del equipo. Tu rol y permisos del sistema solo pueden ser cambiados por un administrador.')}</div></div></section>`);
 const av=document.querySelector('#profile-avatar-large');if(avatar){const im=document.createElement('img');im.src=avatar;im.alt=tr('Profile photo','Foto de perfil');av.appendChild(im)}else av.textContent=initials;
 const msg=document.querySelector('#profile-message');
 document.querySelector('#member-profile-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]'),d=new FormData(e.target),firstName=String(d.get('first_name')||'').trim(),lastName=String(d.get('last_name')||'').trim(),position=String(d.get('position')||'').trim(),jobsiteId=String(d.get('jobsite_id')||'').trim(),bio=String(d.get('bio')||'').trim(),phone=String(d.get('phone')||'').trim(),notifySms=d.get('notify_sms')==='on',notifyApp=d.get('notify_app')==='on',notifyEmail=d.get('notify_email')==='on';if(phone&&!/^\+?[0-9 ()-]{10,20}$/.test(phone))return error(tr('Enter a valid mobile phone number including area code.','Ingrese un número móvil válido incluyendo código de área.'));if(notifySms&&!phone)return error(tr('Add a mobile phone number to enable SMS notifications.','Agregue un teléfono móvil para activar notificaciones SMS.'));if(!firstName||!lastName||!position||!jobsiteId)return error(tr('Complete all profile fields.','Completa todos los campos del perfil.'));b.disabled=true;msg.textContent=tr('Saving profile…','Guardando perfil…');const changes={first_name:firstName,last_name:lastName,name:firstName+' '+lastName,position,jobsite_id:jobsiteId,bio,phone:phone||null,notify_sms:notifySms,notify_app:notifyApp,notify_email:notifyEmail,updated_at:new Date().toISOString()};const saved=await db.from('profiles').update(changes).eq('id',p.id).select('*').single();b.disabled=false;if(saved.error){msg.textContent=saved.error.message;return}state.profile=saved.data;msg.textContent=tr('Profile saved successfully.','Perfil guardado correctamente.');setTimeout(()=>profilePage(),500)};
 document.querySelector('#profile-photo').onchange=async e=>{let file=e.target.files?.[0];if(!file)return;const allowed=['image/jpeg','image/png','image/webp','image/heic','image/heif'];if(file.size>5242880){msg.textContent=tr('Photo must be 5 MB or smaller.','La foto debe ser de 5 MB o menos.');return}if(!allowed.includes(file.type)&&!/\.hei[cf]$/i.test(file.name)){msg.textContent=tr('Choose a JPG, PNG, WEBP or HEIC image.','Elige una imagen JPG, PNG, WEBP o HEIC.');return}msg.textContent=tr('Preparing photo…','Preparando foto…');try{file=await normalizeReportImage(file)}catch(err){msg.textContent=err?.message||tr('Could not prepare this photo.','No se pudo preparar esta foto.');return}try{file=await cropProfilePhoto(file)}catch(err){msg.textContent=tr('Could not open the photo editor.','No se pudo abrir el editor de foto.');return}if(!file){msg.textContent=tr('Photo change canceled.','Cambio de foto cancelado.');return}if(file.size>5242880){msg.textContent=tr('Converted photo is larger than 5 MB. Choose another photo.','La foto convertida supera 5 MB. Elige otra foto.');return}msg.textContent=tr('Uploading photo…','Subiendo foto…');const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,''),path=p.id+'/avatar-'+Date.now()+'.'+ext;const up=await db.storage.from('profile-avatars').upload(path,file,{contentType:file.type||'image/jpeg',cacheControl:'3600',upsert:false});if(up.error){msg.textContent=up.error.message;return}const old=p.avatar_path,saved=await db.from('profiles').update({avatar_path:path,updated_at:new Date().toISOString()}).eq('id',p.id).select('*').single();if(saved.error){await db.storage.from('profile-avatars').remove([path]);msg.textContent=saved.error.message;return}if(old)await db.storage.from('profile-avatars').remove([old]);state.profile=saved.data;profilePage()};
}
function setPassword(){frame(`<section class="card narrow"><h1>${tr('Set your password','Crea tu contraseña')}</h1><form id="password-form"><label>${tr('New password','Nueva contraseña')}<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label>${tr('Confirm password','Confirmar contraseña')}<input type="password" name="confirmation" required minlength="8" autocomplete="new-password"></label><button>${tr('Save password','Guardar contraseña')}</button></form></section>`);document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),p=String(f.get('password'));if(p!==f.get('confirmation'))return error(tr('Passwords do not match','Las contraseñas no coinciden'));const {error:err}=await db.auth.updateUser({password:p});if(err)return error(err);state.page='home';await refresh()}}
async function refresh(){const {data:{session}}=await db.auth.getSession();state.session=session;await load();render()}
async function load(){if(!state.session){state.profile=null;return}const p=await db.from('profiles').select('*').eq('id',state.session.user.id).maybeSingle();if(p.error)return error(p.error);state.profile=p.data;if(!p.data)return;const [projects,obs]=await Promise.all([db.from('projects').select('*').order('name'),db.from('observations').select('*, creator:profiles!observations_created_by_fkey(name), assignee:profiles!observations_assigned_to_fkey(name), foreman:profiles!observations_foreman_id_fkey(name), jobsite_safety:profiles!observations_jobsite_safety_id_fkey(name)').order('created_at',{ascending:false})]);if(projects.error||obs.error)return error(projects.error||obs.error);state.projects=projects.data;state.observations=obs.data;if(!state.projects.some(x=>x.id===state.project))state.project=state.projects[0]?.id||null}
function nav(){return `<div class="toolbar"><select id="project">${state.projects.map(p=>`<option value="${p.id}" ${p.id===state.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button id="report">${tr('Daily report','Reporte diario')}</button><button id="new">+ ${tr('Observation','Observación')}</button>${state.profile.role==='admin'?`<button id="admin">${tr('Projects & team','Proyectos y equipo')}</button>`:''}</div>`}
function bindNav(){document.querySelector('#project').onchange=e=>{state.project=e.target.value;render()};document.querySelector('#report').onclick=()=>navigate('report');document.querySelector('#new').onclick=()=>navigate('new');const a=document.querySelector('#admin');if(a)a.onclick=()=>navigate('admin')}
function openAppMenu(){const old=document.querySelector('.app-menu-overlay');if(old)return old.remove();const overlay=document.createElement('div');overlay.className='app-menu-overlay';const adminLink=state.profile?.role==='admin'?'<button data-go="admin"><span>▦</span>'+tr('Projects & Team','Proyectos y Equipo')+'</button>':'';const disciplineLink=['admin','safety_director','safety'].includes(state.profile?.role)?'<button data-go="discipline"><span>⚠</span>'+tr('Disciplinary Actions','Acciones Disciplinarias')+'</button>':'';overlay.innerHTML='<aside class="app-menu-panel"><div class="app-menu-head"><div class="app-menu-brand"><img src="/ge-logo.png" alt="G&E"><div><strong>G&E</strong><span>SAFETY DEPARTMENT</span></div></div><button id="app-menu-close" aria-label="'+tr('Close','Cerrar')+'">×</button></div><nav class="app-menu-links"><button data-go="home"><span>⌂</span>'+tr('Dashboard','Panel Principal')+'</button>'+adminLink+'<button data-go="observations"><span>☷</span>'+tr('Safety Observations','Observaciones de Safety')+'</button><button data-go="corrections"><span>✓</span>'+tr('Corrective Actions','Acciones Correctivas')+'</button><button data-go="safetyWalk"><span>☑</span>'+tr('Daily Safety Walk','Daily Safety Walk')+'</button>'+disciplineLink+'<button data-go="reportCenter"><span>▤</span>'+tr('Reports & Export','Reportes y Exportación')+'</button><button data-go="notifications"><span>♢</span>'+tr('Notifications','Notificaciones')+'</button><button data-go="setPassword"><span>⚙</span>'+tr('Settings','Configuración')+'</button></nav><div class="app-menu-foot"><small>'+esc(state.profile?.name||state.session?.user?.email||'G&E Team')+'</small><button id="app-menu-logout">⇥ '+tr('Logout','Salir')+'</button></div></aside>';document.body.appendChild(overlay);requestAnimationFrame(()=>overlay.classList.add('show'));overlay.onclick=e=>{if(e.target===overlay)overlay.remove()};overlay.querySelector('#app-menu-close').onclick=()=>overlay.remove();overlay.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{overlay.remove();const p=b.dataset.go;p==='home'?navigate('home'):navigate(p)});overlay.querySelector('#app-menu-logout').onclick=()=>db.auth.signOut();}
async function home(){const homeAvatar=await profileAvatarUrl(state.profile?.avatar_path);const rows=state.observations.filter(o=>o.project_id===state.project),open=rows.filter(o=>o.status==='open').length,pending=rows.filter(o=>o.status==='pending_verification').length,closed=rows.filter(o=>o.status==='closed').length,highOpen=rows.filter(o=>o.priority==='high'&&o.status!=='closed').length,myOpen=rows.filter(o=>o.assigned_to===state.profile.id&&o.status!=='closed').length,todayKey=localDateKey(new Date()),walkCheck=await db.from('daily_safety_walks').select('id,overall_status,created_at').eq('project_id',state.project).order('created_at',{ascending:false}).limit(20),todayWalk=(walkCheck.data||[]).find(x=>localDateKey(x.created_at)===todayKey),name=state.profile?.name?.split(' ')[0]||tr('Team','Equipo'),hour=new Date().getHours(),greeting=hour<12?tr('Good morning','Buenos días'):hour<18?tr('Good afternoon','Buenas tardes'):tr('Good evening','Buenas noches'),initials=(state.profile?.name||'GE').split(/\\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),today=new Intl.DateTimeFormat(state.lang==='es'?'es-US':'en-US',{dateStyle:'long'}).format(new Date());frame(`<section class="home-shell"><div class="home-welcome"><div><h1>${greeting}, ${esc(name)}</h1><p>${tr('Safety Today. A Safer Tomorrow.','Seguridad hoy. Un mañana más seguro.')}</p></div><button type="button" class="user-avatar home-profile-button" id="home-profile" aria-label="${tr('Open my profile','Abrir mi perfil')}">${homeAvatar?`<img src="${esc(homeAvatar)}" alt="${tr('My profile photo','Mi foto de perfil')}">`:esc(initials)}</button></div><div class="project-label">${tr('Project','Proyecto')}</div><select class="project-picker" id="home-project">${state.projects.map(p=>`<option value="${p.id}" ${p.id===state.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select><div class="today-line"><span>${tr('Today','Hoy')}</span><span>${esc(today)}</span></div><section class="command-center"><div class="command-head"><div><small>${tr("SAFETY COMMAND CENTER","CENTRO DE CONTROL SAFETY")}</small><h2>${tr("Today’s Priorities","Prioridades de Hoy")}</h2></div><span>${esc(today)}</span></div><div class="command-grid"><button class="command-alert high" id="cmd-high"><strong>${highOpen}</strong><span>${tr("High Priority Open","Prioridad Alta Abierta")}</span><small>${tr("Requires attention","Requiere atención")}</small></button><button class="command-alert mine" id="cmd-mine"><strong>${myOpen}</strong><span>${tr("My Open Tasks","Mis Tareas Abiertas")}</span><small>${tr("Assigned directly to you","Asignadas directamente a usted")}</small></button><button class="command-alert review" id="cmd-review"><strong>${pending}</strong><span>${tr("Waiting Safety Review","Esperando Revisión Safety")}</span><small>${tr("Corrections to verify","Correcciones por verificar")}</small></button><button class="command-alert walk ${todayWalk?"done":"due"}" id="cmd-walk"><strong>${todayWalk?"✓":"!"}</strong><span>${todayWalk?tr("Daily Walk Completed","Daily Walk Completado"):tr("Daily Walk Pending","Daily Walk Pendiente")}</span><small>${todayWalk?fmt(todayWalk.created_at):tr("Create today’s inspection","Crear inspección de hoy")}</small></button></div></section><div class="home-actions"><button class="home-action blue" id="home-new"><span class="action-icon">📷</span><span>${tr('New Observation','Nueva observación')}</span></button><button class="home-action green" id="home-observations"><span class="action-icon">☷</span><span>${tr('Observations','Observaciones')}</span></button><button class="home-action orange" id="home-corrections"><span class="action-icon">✓</span><span>${tr('Corrections','Correcciones')}</span></button><button class="home-action purple report-module" id="home-report"><span class="action-icon report-icon" aria-hidden="true"><span class="report-sheet-lines"></span></span><span>${tr('Daily Report','Reporte diario')}</span></button><button class="home-action cloud-backup-module" id="home-cloud-backup"><span class="action-icon">☁</span><span>${tr('Cloud Backup','Respaldo en la Nube')}</span></button><button class="home-action equipment-module" id="home-equipment"><span class="action-icon">⌕</span><span>${tr('Equipment Inspections','Inspección de Equipos')}</span></button><button class="home-action slate" id="home-team"><span class="action-icon">👥</span><span>${tr('Team','Equipo')}</span></button><button class="home-action settings" id="home-settings"><span class="action-icon">⚙</span><span>${tr('Settings','Configuración')}</span></button>${['admin','safety_director','safety'].includes(state.profile.role)?`<button class="home-action discipline" id="home-discipline"><span class="action-icon">⚠</span><span>${tr('Disciplinary Actions','Acciones de Disciplina')}</span></button>`:''}<button class="home-action safety-walk" id="home-safety-walk"><span class="action-icon">✓</span><span>${tr('Create Daily Report','Crear Daily Report')}</span></button><button class="home-action incident-action" id="home-incident"><span class="action-icon">!</span><span>${tr('Create Incident / Accident Report','Crear Reporte de Accidente / Incidente')}</span></button></div><div class="home-stats"><div class="home-stat"><strong>${open}</strong>${tr('Open','Abiertas')}</div><div class="home-stat"><strong>${pending}</strong>${tr('In progress','En proceso')}</div><div class="home-stat"><strong>${closed}</strong>${tr('Closed','Cerradas')}</div></div></section><div class="mobile-bottom"><button class="active" id="bottom-home"><span>⌂</span>${tr('Home','Inicio')}</button><button id="bottom-observations"><span>📷</span>${tr('Observations','Observaciones')}</button><button id="bottom-report" class="bottom-report"><span class="bottom-report-icon" aria-hidden="true"></span>${tr('Report','Reporte')}</button><button id="bottom-team"><span>👥</span>${tr('Team','Equipo')}</button><button id="bottom-more"><span>•••</span>${tr('More','Más')}</button></div>`);const project=document.querySelector('#home-project');if(project)project.onchange=e=>{state.project=e.target.value;render()};const goNew=()=>navigate('new'),goObs=()=>navigate('observations'),goCorrections=()=>navigate('corrections'),goReport=()=>navigate('reportCenter'),goTeam=()=>{if(state.profile.role==='admin')navigate('admin');else error(tr('Team management is available to administrators.','La administración del equipo está disponible para administradores.'))};document.querySelector('#home-profile').onclick=()=>navigate('profile');document.querySelector('#cmd-high').onclick=goObs;document.querySelector('#cmd-mine').onclick=goObs;document.querySelector('#cmd-review').onclick=goCorrections;document.querySelector('#cmd-walk').onclick=()=>todayWalk?navigate('safetyWalkReport',todayWalk.id):navigate('safetyWalk');document.querySelector('#home-new').onclick=goNew;document.querySelector('#home-observations').onclick=goObs;document.querySelector('#home-corrections').onclick=goCorrections;document.querySelector('#home-report').onclick=goReport;document.querySelector('#home-cloud-backup').onclick=()=>navigate('cloudBackup');document.querySelector('#home-equipment').onclick=()=>navigate('equipmentInspection');document.querySelector('#home-team').onclick=goTeam;document.querySelector('#home-settings').onclick=()=>navigate('setPassword');const disciplineBtn=document.querySelector('#home-discipline');if(disciplineBtn)disciplineBtn.onclick=()=>navigate('discipline');document.querySelector('#home-safety-walk').onclick=()=>navigate('safetyWalk');document.querySelector('#home-incident').onclick=()=>navigate('incident');document.querySelector('#bottom-home').onclick=()=>render();document.querySelector('#bottom-observations').onclick=goObs;document.querySelector('#bottom-report').onclick=goReport;document.querySelector('#bottom-team').onclick=goTeam;const more=document.querySelector('#bottom-more');if(more)more.onclick=openAppMenu}
function observationsList(){const rows=state.observations.filter(o=>o.project_id===state.project),counts={open:rows.filter(o=>o.status==='open').length,pending:rows.filter(o=>o.status==='pending_verification').length,closed:rows.filter(o=>o.status==='closed').length};frame(`<section class="observations-shell"><div class="section-heading"><div><h1>${tr('Safety Observations','Observaciones de seguridad')}</h1><p>${tr('Track hazards, corrections and Safety verification.','Controla peligros, correcciones y verificación de Safety.')}</p></div><button id="obs-new">+ ${tr('New Observation','Nueva observación')}</button></div><div class="obs-summary" role="tablist" aria-label="${tr('Observation status','Estado de observaciones')}"><button class="summary-chip all active" data-status="all" role="tab"><span class="status-mark">●</span><span class="status-copy"><small>${tr('All','Todas')}</small><strong>${rows.length}</strong></span></button><button class="summary-chip open" data-status="open" role="tab"><span class="status-mark">!</span><span class="status-copy"><small>${tr('Open','Abiertas')}</small><strong>${counts.open}</strong></span></button><button class="summary-chip progress" data-status="pending_verification" role="tab"><span class="status-mark">↻</span><span class="status-copy"><small>${tr('In Progress','En proceso')}</small><strong>${counts.pending}</strong></span></button><button class="summary-chip closed" data-status="closed" role="tab"><span class="status-mark">✓</span><span class="status-copy"><small>${tr('Closed','Cerradas')}</small><strong>${counts.closed}</strong></span></button></div><div class="obs-tools"><input id="obs-search" type="search" placeholder="${tr('Search area, category or observation...','Buscar área, categoría u observación...')}"><select id="obs-priority"><option value="all">${tr('All priorities','Todas las prioridades')}</option><option value="high">${tr('High priority','Prioridad alta')}</option><option value="medium">${tr('Medium priority','Prioridad media')}</option><option value="low">${tr('Low priority','Prioridad baja')}</option></select></div><div id="obs-list" class="obs-list"></div></section>`);let status='all';const paint=()=>{const q=document.querySelector('#obs-search').value.trim().toLowerCase(),priority=document.querySelector('#obs-priority').value,list=document.querySelector('#obs-list');const filtered=rows.filter(o=>(status==='all'||o.status===status)&&(priority==='all'||o.priority===priority)&&(!q||[o.area,o.category,o.description,o.assignee?.name].some(v=>String(v||'').toLowerCase().includes(q))));list.innerHTML=filtered.length?filtered.map(o=>`<button class="obs-card" data-id="${o.id}"><div class="obs-card-top"><span class="badge ${esc(o.priority)}">${o.priority==='high'?tr('HIGH','ALTA'):o.priority==='medium'?tr('MEDIUM','MEDIA'):tr('LOW','BAJA')}</span><span class="obs-status">${o.status==='pending_verification'?tr('IN PROGRESS','EN PROCESO'):o.status==='closed'?tr('CLOSED','CERRADA'):tr('OPEN','ABIERTA')}</span></div><h3>${esc(o.area)}</h3><p class="obs-category">${esc(o.category)}</p><p>${esc(o.description)}</p><div class="obs-meta"><span>${esc(o.assignee?.name||tr('Unassigned','Sin asignar'))}</span><span>${fmt(o.created_at)}</span></div></button>`).join(''):`<div class="empty-state"><strong>${tr('No observations found','No se encontraron observaciones')}</strong><p>${tr('Change the filters or create a new observation.','Cambia los filtros o crea una nueva observación.')}</p></div>`;list.querySelectorAll('[data-id]').forEach(el=>el.onclick=async()=>{state.detail=el.dataset.id;await markViewed(state.detail);navigate('detail',state.detail)})};document.querySelector('#obs-new').onclick=()=>navigate('new');document.querySelector('#obs-search').oninput=paint;document.querySelector('#obs-priority').onchange=paint;document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;document.querySelectorAll('[data-status]').forEach(x=>x.classList.toggle('active',x===b));paint()});paint()}
function correctionsList(){const rows=state.observations.filter(o=>o.project_id===state.project&&o.status==='pending_verification');frame(`<section class="observations-shell"><div class="section-heading"><div><h1>${tr('Corrections','Correcciones')}</h1><p>${tr('Review completed corrective actions before final closure.','Revisa las acciones correctivas completadas antes del cierre final.')}</p></div></div><div class="review-banner"><strong>${rows.length}</strong><span>${tr('Awaiting Safety review','Esperando revisión de Safety')}</span></div><div class="obs-list">${rows.length?rows.map(o=>`<button class="obs-card correction-card" data-id="${o.id}"><div class="obs-card-top"><span class="badge ${esc(o.priority)}">${o.priority==='high'?tr('HIGH','ALTA'):o.priority==='medium'?tr('MEDIUM','MEDIA'):tr('LOW','BAJA')}</span><span class="obs-status">${tr('READY FOR REVIEW','LISTA PARA REVISIÓN')}</span></div><h3>${esc(o.area)}</h3><p class="obs-category">${esc(o.category)}</p><p>${esc(o.description)}</p><div class="obs-meta"><span>${esc(o.assignee?.name||tr('Unassigned','Sin asignar'))}</span><span>${fmt(o.created_at)}</span></div></button>`).join(''):`<div class="empty-state"><strong>${tr('No corrections awaiting review','No hay correcciones esperando revisión')}</strong><p>${tr('Completed corrections will appear here automatically.','Las correcciones completadas aparecerán aquí automáticamente.')}</p></div>`}</div></section>`);document.querySelectorAll('[data-id]').forEach(el=>el.onclick=async()=>{state.detail=el.dataset.id;await markViewed(state.detail);navigate('detail',state.detail)})}
let presenceTimer=null;
async function updateAppPresence(){if(!state.session||!state.profile)return;const payload={user_id:state.profile.id,last_seen_at:new Date().toISOString(),updated_at:new Date().toISOString()};try{if(navigator.geolocation&&!sessionStorage.getItem('ge_location_denied'))navigator.geolocation.getCurrentPosition(pos=>db.from('user_app_presence').upsert({...payload,latitude:pos.coords.latitude,longitude:pos.coords.longitude,location_accuracy_m:pos.coords.accuracy,location_updated_at:new Date().toISOString()}),()=>{sessionStorage.setItem('ge_location_denied','1')},{enableHighAccuracy:false,maximumAge:300000,timeout:5000});await db.from('user_app_presence').upsert(payload)}catch{}}
function startAppPresence(){if(presenceTimer)clearInterval(presenceTimer);updateAppPresence();presenceTimer=setInterval(updateAppPresence,60000)}

async function admin(){if(state.profile.role!=='admin'){state.page='home';return render()}const [people,members,teamActivity]=await Promise.all([db.from('profiles').select('id,email,name,role,position').order('name'),db.from('project_members').select('project_id,user_id'),db.functions.invoke('team-activity')]);if(people.error||members.error)return error(people.error||members.error);const teamMembers=teamActivity.data?.members||people.data.map(p=>({...p,auth_status:'pending',projects:[],activity:{observations:0,corrections:0,daily_reports:0,disciplinary_actions:0,total_actions:0}}));frame(`<button class="secondary" id="back">← ${tr('Back','Atrás')}</button><section class="card"><h1>${tr('Projects and team','Proyectos y equipo')}</h1><form id="add-project"><label>${tr('Project name','Nombre del proyecto')}<input name="name" required maxlength="120"></label><label>${tr('Jobsite address','Dirección de la obra')}<input name="address" maxlength="240"></label><label>${tr('General contractor','Contratista general')}<input name="general_contractor" maxlength="120"></label><button>${tr('Create project','Crear proyecto')}</button></form></section><section class="card invite-card"><div class="section-heading"><div><h2>${tr('Invite team member','Invitar miembro del equipo')}</h2><p>${tr('The employee receives an email, opens the secure link and creates their own password.','El empleado recibe un correo, abre el enlace seguro y crea su propia contraseña.')}</p></div></div><form id="invite-member"><label>${tr('Full name','Nombre completo')}<input name="name" required maxlength="120"></label><label>${tr('Company email','Correo de la compañía')}<input name="email" type="email" required placeholder="name@geflcontractors.com"></label><label>${tr('Role','Rol')}<select name="role" required><option value="worker">${tr('Worker','Worker')}</option><option value="supervisor">${tr('Supervisor','Supervisor')}</option><option value="safety">${tr('Safety','Safety')}</option><option value="safety_director">${tr('Safety Director','Director de Safety')}</option></select></label><label>${tr('Authorized project','Proyecto autorizado')}<select name="project_id" required>${state.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><button type="submit">✉ ${tr('Send email invitation','Enviar invitación por correo')}</button><div id="invite-result" class="invite-result"></div></form></section><section class="card team-control"><div class="section-heading"><div><h2>${tr('Team Access & Activity','Acceso y Actividad del Team')}</h2><p>${tr('See who accepted the invitation, who has entered the app and the safety work recorded by each member.','Vea quién aceptó la invitación, quién ha entrado al app y el trabajo de Safety registrado por cada miembro.')}</p></div></div><div class="team-status-legend"><span class="team-dot active"></span>${tr('Activated','Activado')} <span class="team-dot invited"></span>${tr('Invited','Invitado')} <span class="team-dot pending"></span>${tr('Pending','Pendiente')}</div><div class="team-dashboard">${teamMembers.map(p=>{const a=p.activity||{},accepted=p.auth_status==='active',signed=!!p.last_sign_in_at,status=p.active_now?tr('Active Now','Activo Ahora'):accepted?(signed?tr('Has Used App','Ha Usado el App'):tr('Invitation Accepted','Invitación Aceptada')):p.auth_status==='invited'?tr('Invitation Sent','Invitación Enviada'):tr('Pending Activation','Pendiente de Activación'),projects=(p.projects||[]).map(x=>x.name).join(', ')||tr('No project assigned','Sin proyecto asignado');return `<article class="team-user-card"><header><div class="team-avatar">${esc((p.name||p.email||'?').trim().charAt(0).toUpperCase())}</div><div><h3>${esc(p.name||p.email)}</h3><span>${esc(p.email)}</span><small>${esc(p.position||'')} ${p.position?' · ':''}${esc(p.role.replaceAll('_',' '))}</small></div><b class="team-state ${esc(p.auth_status)}">${esc(status)}</b></header><div class="team-user-meta"><div><small>${tr('PROJECTS','PROYECTOS')}</small><strong>${esc(projects)}</strong></div><div><small>${tr('INVITED','INVITADO')}</small><strong>${esc(p.invited_at?fmt(p.invited_at):'—')}</strong></div><div><small>${tr('ACCEPTED','ACEPTÓ')}</small><strong>${esc(p.accepted_at?fmt(p.accepted_at):'—')}</strong></div><div><small>${tr('LAST SIGN IN','ÚLTIMO INGRESO')}</small><strong>${esc(p.last_sign_in_at?fmt(p.last_sign_in_at):tr('Never','Nunca'))}</strong></div><div><small>${tr('APP STATUS','ESTADO APP')}</small><strong class="presence-state ${p.active_now?'online':'offline'}">${p.active_now?'● '+tr('ACTIVE NOW','ACTIVO AHORA'):'○ '+tr('OFFLINE','DESCONECTADO')}</strong></div><div><small>${tr('LAST APP ACTIVITY','ÚLTIMA ACTIVIDAD APP')}</small><strong>${esc(p.last_app_activity_at?fmt(p.last_app_activity_at):tr('Never','Nunca'))}</strong></div><div><small>${tr('LOCATION','LOCALIZACIÓN')}</small><strong>${p.location?esc(p.location.latitude.toFixed(5)+', '+p.location.longitude.toFixed(5))+'<small class="location-detail">±'+Math.round(p.location.accuracy_m||0)+'m · '+esc(p.location.updated_at?fmt(p.location.updated_at):'')+'</small>':tr('Location not shared','Localización no compartida')}</strong></div></div><div class="team-activity-grid"><div><strong>${a.observations||0}</strong><span>${tr('Observations','Observaciones')}</span></div><div><strong>${a.corrections||0}</strong><span>${tr('Corrections','Correcciones')}</span></div><div><strong>${a.daily_reports||0}</strong><span>Daily Reports</span></div><div><strong>${a.disciplinary_actions||0}</strong><span>${tr('Discipline','Disciplina')}</span></div></div><footer><div class="team-footer-stats"><span>${tr('Recorded actions','Acciones registradas')}: <b>${a.total_actions||0}</b></span><span>${tr('Last recorded work','Último trabajo registrado')}: <b>${a.last_action_at?esc(fmt(a.last_action_at)):tr('No activity yet','Sin actividad')}</b></span></div>${p.id!==state.profile.id?`<button type="button" class="team-remove-member" data-user-id="${esc(p.id)}" data-user-name="${esc(p.name||p.email)}">× ${tr('Remove Member','Eliminar miembro')}</button>`:''}</footer></article>`}).join('')}</div></section>`);document.querySelector('#back').onclick=back;document.querySelectorAll('.team-remove-member').forEach(btn=>btn.onclick=async()=>{const userId=btn.dataset.userId,userName=btn.dataset.userName||tr('this member','este miembro');if(!userId||userId===state.profile.id)return;const assigned=members.data.filter(m=>m.user_id===userId),assignedProjects=state.projects.filter(p=>assigned.some(m=>m.project_id===p.id));if(!assignedProjects.length){window.alert(tr('This member has no project access to remove.','Este miembro no tiene acceso a proyectos para eliminar.'));return}let target=assignedProjects[0];if(assignedProjects.length>1){const choices=assignedProjects.map((p,i)=>`${i+1}. ${p.name}`).join('\n'),answer=window.prompt(tr(`Choose the project access to remove for ${userName}:\n${choices}\n\nEnter the project number.`,`Elige el proyecto del cual deseas quitar a ${userName}:\n${choices}\n\nEscribe el número del proyecto.`));if(answer===null)return;const index=Number.parseInt(answer,10)-1;if(!Number.isInteger(index)||!assignedProjects[index]){window.alert(tr('Invalid project selection. No changes were made.','Selección de proyecto inválida. No se realizó ningún cambio.'));return}target=assignedProjects[index]}const confirmed=window.confirm(tr(`Remove ${userName} from ${target.name}? Their account, other project access and existing safety records will NOT be deleted.`,`¿Eliminar a ${userName} de ${target.name}? Su cuenta, acceso a otros proyectos y reportes existentes NO serán eliminados.`));if(!confirmed)return;btn.disabled=true;btn.textContent=tr('Removing…','Eliminando…');const del=await db.from('project_members').delete().eq('user_id',userId).eq('project_id',target.id);if(del.error){btn.disabled=false;btn.textContent='× '+tr('Remove Member','Eliminar miembro');return error(del.error)}await load();admin()});document.querySelector('#add-project').onsubmit=async ev=>{ev.preventDefault();const d=new FormData(ev.target),r=await db.from('projects').insert({name:d.get('name'),address:d.get('address'),general_contractor:d.get('general_contractor')});if(r.error)return error(r.error);await load();admin()};document.querySelector('#invite-member').onsubmit=async ev=>{ev.preventDefault();const form=ev.target,button=form.querySelector('button[type="submit"]'),out=document.querySelector('#invite-result'),d=new FormData(form),email=String(d.get('email')).trim().toLowerCase();if(!email.endsWith('@geflcontractors.com')){out.className='invite-result error';out.textContent=tr('Only @geflcontractors.com company emails are allowed.','Solo se permiten correos de la compañía @geflcontractors.com.');return}button.disabled=true;out.className='invite-result';out.textContent=tr('Sending invitation...','Enviando invitación...');const {data:result,error:err}=await db.functions.invoke('invite-team-member',{body:{name:d.get('name'),email,role:d.get('role'),project_id:d.get('project_id'),redirect_to:window.location.origin}});button.disabled=false;if(err||result?.error){out.className='invite-result error';out.textContent=result?.error||err?.message||tr('Invitation could not be sent.','No se pudo enviar la invitación.');return}out.className='invite-result success';out.textContent=result?.existing?tr('Existing team member added to this project successfully.','Miembro existente agregado correctamente a este proyecto.'):tr('Invitation sent. The employee must check their email and create their password.','Invitación enviada. El empleado debe revisar su correo y crear su contraseña.');form.reset();await load();admin()}}

