async function cloudBackup(){
 if(!['admin','safety_director'].includes(state.profile.role))return error(tr('Only Admin or Safety Director can create cloud backups.','Solo Admin o Safety Director puede crear respaldos.'));
 const project=state.projects.find(p=>p.id===state.project);if(!project)return error(tr('Select a project first.','Seleccione un proyecto primero.'));
 const q=await db.from('cloud_backups').select('*').eq('project_id',state.project).order('created_at',{ascending:false}).limit(30);if(q.error)return error(q.error);const rows=q.data||[];
 const history=rows.length?rows.map(b=>'<div class="backup-row"><span class="backup-state '+esc(b.status)+'">'+(b.status==='completed'?'✓ ':'')+esc(b.status.toUpperCase())+'</span><div><b>'+esc(b.backup_number)+'</b><small>'+esc(fmt(b.created_at))+' · '+b.file_count+' files · '+formatBackupBytes(b.total_bytes)+'</small></div>'+(b.manifest_path?'<button data-manifest="'+esc(b.manifest_path)+'">'+tr('Verify / Manifest','Verificar / Manifest')+'</button>':'')+'</div>').join(''):'<p class="empty-state">'+tr('No backups created yet.','Aún no se han creado respaldos.')+'</p>';
 frame('<section class="backup-shell"><div class="backup-hero"><span>☁</span><div><small>G&E SAFETY DEPARTMENT</small><h1>'+tr('Cloud Backup Center','Centro de Respaldo en la Nube')+'</h1><p>'+tr('Protect project records, reports, PDFs and photo evidence with a verified backup copy.','Proteja registros, reportes, PDFs y evidencia fotográfica del proyecto con una copia de respaldo verificada.')+'</p></div></div><div class="backup-status-card"><div><small>'+tr('CURRENT PROJECT','PROYECTO ACTUAL')+'</small><b>'+esc(project.name)+'</b></div><div><small>'+tr('PRIMARY STORAGE','ALMACENAMIENTO PRINCIPAL')+'</small><b>Supabase Storage · Private</b></div><div><small>'+tr('BACKUP ENGINE','MOTOR DE RESPALDO')+'</small><b>G&E Verified Backup v1</b></div></div><div class="backup-card"><h2>'+tr('Create Verified Backup','Crear Respaldo Verificado')+'</h2><p>'+tr('Creates a protected project snapshot containing safety records plus copies of final PDFs and uploaded evidence.','Crea una copia protegida del proyecto con registros de Safety más copias de PDFs finales y evidencia cargada.')+'</p><div class="backup-includes"><span>✓ Observations</span><span>✓ Daily Reports</span><span>✓ Incidents</span><span>✓ Equipment Inspections</span><span>✓ Disciplinary Records</span><span>✓ Final PDFs</span><span>✓ Photos / Evidence</span><span>✓ Audit Metadata</span></div><button id="create-cloud-backup" class="backup-create">☁ '+tr('Back Up This Project Now','Respaldar Este Proyecto Ahora')+'</button><p class="backup-security">🔒 '+tr('Private backup with project-controlled access.','Respaldo privado con acceso controlado por proyecto.')+'</p></div><div class="backup-card"><h2>'+tr('External Cloud Ready','Preparado para Nube Externa')+'</h2><div class="backup-providers"><span><b>Google Drive</b><small>OAuth 2.0 · Drive API</small><em class="cloud-provider-status">'+tr('Connection required','Requiere conexión')+'</em></span><span><b>Dropbox</b><small>OAuth 2.0 · Dropbox API</small><em class="cloud-provider-status">'+tr('Connection required','Requiere conexión')+'</em></span><span><b>Cloudflare R2</b><small>S3 compatible · recommended</small></span><span><b>Amazon S3</b><small>S3 compatible</small></span><span><b>Backblaze B2</b><small>S3 compatible</small></span><span><b>Wasabi</b><small>S3 compatible</small></span></div><p class="backup-note">'+tr('External credentials are never stored in the browser; automatic replication is enabled only after a server-side cloud connection is configured.','Las credenciales externas nunca se guardan en el navegador; la replicación automática se activa solo después de configurar una conexión segura del servidor.')+'</p></div><div class="backup-card"><h2>'+tr('Backup History','Historial de Respaldos')+'</h2><div class="backup-history">'+history+'</div></div></section>');
 document.querySelector('#create-cloud-backup').onclick=async e=>{const btn=e.currentTarget;btn.disabled=true;btn.textContent=tr('Creating and verifying backup…','Creando y verificando respaldo…');try{const {data,error:fnError}=await db.functions.invoke('create-cloud-backup',{body:{project_id:state.project}});if(fnError)throw fnError;if(!data?.ok)throw Error(data?.error||'Backup failed');await cloudBackup()}catch(err){error(err);btn.disabled=false;btn.textContent=tr('Back Up This Project Now','Respaldar Este Proyecto Ahora')}};
 document.querySelectorAll('[data-manifest]').forEach(btn=>btn.onclick=async()=>{const {data,error:e}=await db.storage.from('cloud-backups').createSignedUrl(btn.dataset.manifest,120);if(e)return window.alert(e.message);window.open(data.signedUrl,'_blank','noopener')});
}
function formatBackupBytes(n){n=Number(n||0);if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';if(n<1073741824)return (n/1048576).toFixed(1)+' MB';return (n/1073741824).toFixed(2)+' GB'}

