 <section><h2>1. INCIDENT CLASSIFICATION</h2><div class="ir-grid"><p><b>Type:</b> ${esc(r.incident_type.replaceAll('_',' '))}</p><p><b>Severity:</b> ${esc(r.severity)}</p><p><b>Exact Location:</b> ${esc(r.exact_location)}</p></div></section>
