async function photoUrl(path){return {data:{signedUrl:await signedDisplayImage('observation-photos',path,3600)}}}
async function detail(){const o=state.observations.find(x=>x.id===state.detail);if(!o){state.page='home';return render()}const [photos,views,actions]=await Promise.all([db.from('observation_photos').select('*').eq('observation_id',o.id),db.from('observation_views').select('*, profile:profiles(name)').eq('observation_id',o.id),db.from('corrective_actions').select('*, author:profiles(name)').eq('observation_id',o.id).order('created_at')]);if(photos.error||views.error||actions.error)return error(photos.error||views.error||actions.error);const signed=await Promise.all(photos.data.map(async p=>({...p,url:(await photoUrl(p.path)).data?.signedUrl})));frame(`<button class="secondary" id="back">← ${tr('Observations','Observaciones')}</button><section class="card"><div class="row"><h1>${esc(o.area)}</h1><span class="badge ${o.priority}">${esc(o.priority)}</span><span class="badge">${esc(o.status)}</span></div><p>${esc(o.description)}</p><p>${esc(o.category)} · ${fmt(o.created_at)} · ${esc(o.creator?.name)}</p><div class="assignment-summary"><span><b>${tr('Assigned Person','Persona asignada')}:</b> ${esc(o.assignee?.name||tr('Unassigned','Sin asignar'))}</span><span><b>${tr('Foreman in Charge','Foreman encargado')}:</b> ${esc(o.foreman?.name||'—')}</span><span><b>${tr('Jobsite Safety','Safety del jobsite')}:</b> ${esc(o.jobsite_safety?.name||'—')}</span></div><div class="photos">${signed.map(p=>`<figure><img src="${esc(p.url)}" alt="${esc(p.kind)}"><figcaption>${p.kind==='before'?tr('Before','Antes'):tr('After','Después')}</figcaption></figure>`).join('')}</div><h2>${tr('Corrective actions','Acciones correctivas')}</h2>${actions.data.map(a=>`<p class="note">${esc(a.comment)}<br><small>${esc(a.author?.name)} · ${fmt(a.created_at)}</small></p>`).join('')}<h2>${tr('Viewed by','Visto por')}</h2>${views.data.map(v=>`<p>${esc(v.profile?.name)} · ${fmt(v.last_viewed_at)}</p>`).join('')||'<p>—</p>'}${o.status==='open'?`<form id="correction"><label>${tr('Correction comment','Comentario de corrección')}<textarea name="comment" required></textarea></label><label>${tr('After photo','Foto después')}<input name="photo" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" required></label><button>${tr('Send for Safety review','Enviar a revisión de Safety')}</button></form>`:''}${o.status==='pending_verification'&&['admin','safety_director','safety'].includes(state.profile.role)?`<button id="close">${tr('Verify and close','Verificar y cerrar')}</button>`:''}</section>`);document.querySelector('#back').onclick=back;const f=document.querySelector('#correction');if(f)f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{const d=new FormData(f),photo=await upload(o.id,'after',d.get('photo'));const r=await db.from('corrective_actions').insert({observation_id:o.id,comment:d.get('comment'),created_by:state.profile.id}).select('id').single();if(r.error){await db.from('observation_photos').delete().eq('id',photo.id);await db.storage.from('observation-photos').remove([photo.path]);throw r.error}const u=await db.from('observations').update({status:'pending_verification'}).eq('id',o.id);if(u.error){await db.from('corrective_actions').delete().eq('id',r.data.id);await db.from('observation_photos').delete().eq('id',photo.id);await db.storage.from('observation-photos').remove([photo.path]);throw u.error}await clearDraft('correction',o.id);await load();detail()}catch(err){error(err)}finally{b.disabled=false}};const c=document.querySelector('#close');if(c)c.onclick=async()=>{const r=await db.from('observations').update({status:'closed',verified_by:state.profile.id,closed_at:new Date().toISOString()}).eq('id',o.id);if(r.error)return error(r.error);await load();detail()}}

